mapper.select:
SELECT COALESCE( SUM( `data_value` ),0) `num`, `NAME` FROM `medical_gas_data`
and `third_device_id` in #{item}
and `collection_time` >= #{startTime}
and `collection_time` <= #{endTime}
GROUP BY `NAME`

SELECT COALESCE( SUM( `data_value` ),0) `num`, `NAME` FROM `medical_gas_data`
and `third_device_id` in #{item}
and `collection_time` >= #{param.period.begin}
and `collection_time` <= #{param.period.end}
GROUP BY `name` order by `num` DESC limit 6

SELECT COALESCE( SUM( `data_value` ), 0 ) `num`, date_format( `collection_time`, ${param.timeFormat} ) AS `timeFlag`, `NAME` FROM `medical_gas_data`
and `third_device_id` in #{item}
and `collection_time` >= #{param.period.begin}
and `collection_time` <= #{param.period.end}
GROUP BY `NAME`, timeFlag ORDER BY `num` DESC

SELECT COALESCE( SUM( `data_value` ), 0 ) `num`, date_format( `collection_time`, ${param.timeFormat} ) AS `timeFlag`, `NAME` FROM `medical_gas_data`
and `third_device_id` in #{item}
and `collection_time` >= #{param.period.begin}
and `collection_time` <= #{param.period.end}
GROUP BY `NAME`, timeFlag ORDER BY `num` DESC

SELECT COALESCE( SUM( `data_value` ), 0 ) `num`, to_char( `collection_time`, ${param.timeFormat} ) AS `timeFlag`, `NAME` FROM `medical_gas_data`
and `third_device_id` in #{item}
and `collection_time` >= #{param.period.begin}
and `collection_time` <= #{param.period.end}
GROUP BY `NAME`, timeFlag ORDER BY `num` DESC

SELECT `area_name` `areaName`, `device_name` `deviceName`, a.`name`, a.`data_value` `dataValue`, a.`collection_time` `collectionTime` FROM `medical_gas_data` a LEFT JOIN `security_device` b ON a.`device_id` = b.`device_id`
and a.`collection_time` >= #{param.period.begin}
and a.`collection_time` <= #{param.period.end}
and b.`device_name` like concat('%',#{param.keyword},'%')
